n (14,''Тимур Рахимов'',NULL,NULL,130000,''2024-05-06'',''timur@corp.ru'',NULL,''middle''),\n (15,''Юлия Седова'',2,5,175000,''2020-09-21'',''yulia@corp.ru'',''+7 843 222-22-25'',''senior'');\n"}');
