INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 4, 's04-41', 40, 'sql', 'Школа: нет оценок', 'Школьная база. Выведите student_id и course_id записей 2024 года, где оценка ещё не выставлена (score IS NULL); по student_id.', '-- Напишите запрос
', '', '{"expected": [[2, 3], [5, 5], [10, 2]], "expected_cols": ["student_id", "course_id"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 4, 's04-42', 41, 'sql', 'Фильмы без рейтинга', 'База фильмов. Выведите title фильмов, у которых рейтинга или режиссёра нет (rating IS NULL OR director_id IS NULL).', '-- Напишите запрос
', '', '{"expected": [["Неизвестный фильм"]], "expected_cols": ["title"], "setup": "CREATE TABLE directors (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  country TEXT NOT NULL\n);\nCREATE TABLE movies (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  genre TEXT NOT NULL,\n  rating REAL,\n  budget INTEGER,\n  director_id INTEGER REFERENCES directors(id)\n);\nINSERT INTO directors VALUES\n (1,''Кристофер Нолан'',''Великобритания''),(2,''Хаяо Миядзаки'',''Япония''),(3,''Андрей Звягинцев'',''Россия''),\n (4,''Грета Гервиг'',''США''),(5,''Дени Вильнёв'',''Канада'');\nINSERT INTO movies VALUES\n (1,''Начало'',2010,''фантастика'',8.8,160,1),(2,''Интерстеллар'',2014,''фантастика'',8.7,165,1),\n (3,''Тёмный рыцарь'',2008,''боевик'',9.0,185,1),(4,''Унесённые призраками'',2001,''анимация'',8.6,19,2),\n (5,''Ходячий замок'',2004,''анимация'',8.2,24,2),(6,''Ветер крепчает'',2013,''анимация'',7.8,30,2),\n (7,''Левиафан'',2014,''драма'',7.6,4,3),(8,''Нелюбовь'',2017,''драма'',7.7,5,3),\n (9,''Барби'',2023,''комедия'',6.9,145,4),(10,''Маленькие женщины'',2019,''драма'',7.8,40,4),\n (11,''Дюна'',2021,''фантастика'',8.0,165,5),(12,''Прибытие'',2016,''фантастика'',7.9,47,5),\n (13,''Неизвестный фильм'',2022,''драма'',NULL,NULL,NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 5, 's05-01', 0, 'sql', 'Сколько клиентов', 'Сколько клиентов в таблице customers? Выведите число как n (COUNT(*)).', 'SELECT COUNT(*) AS n
FROM ...;
', 'COUNT(*) считает строки.', '{"expected": [[12]], "expected_cols": ["n"], "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Кла