),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\nCREATE TABLE cities (city TEXT PRIMARY KEY, country TEXT NOT NULL);\nINSERT INTO cities VALUES (''Москва'', ''Россия''), (''Казань'', ''Россия''), (''Тверь'', ''Россия''), (''Санкт-Петербург'', ''Россия''), (''Омск'', ''Россия'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 6, 's06-08', 7, 'sql', 'Клиенты и заказы (LEFT)', 'Выведите name клиента и id заказа; клиенты без заказов тоже должны быть в результате (LEFT JOIN, order_id будет NULL). По name, затем по order_id.', '-- Напишите запрос
