INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 6, 's06-23', 22, 'sql', 'CROSS JOIN', 'Сколько строк даёт перекрёстное соединение customers CROSS JOIN products? Столбец n.', '-- Напишите запрос
', 'Каждая строка слева с каждой строкой справа: 12 × 13.', '{"expected": [[156]], "expected_cols": ["n"], "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
