INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 7, 's07-25', 24, 'sql', 'HR: сотрудники московских отделов', 'База HR. Выведите name сотрудников отделов, расположенных в Москве (dept_id IN (SELECT id FROM departments WHERE city = ''Москва'')); по id.', '-- Напишите запрос
