INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-11', 10, 'sql', 'OR IGNORE', 'Вставка клиента с уже существующим id завершится ошибкой. INSERT OR IGNORE молча пропускает такую строку. Добавьте через OR IGNORE: (1, ''Дубликат'', ...) и (14, ''Новый'', ...). Столбцы id, name, registered.', '-- Напишите запрос
', '', '{"check": "SELECT id, name, city, email, registered, vip FROM customers ORDER BY id", "expected": [[1, "Анна Петрова", "Москва", "anna@mail.ru", "2024-01-15", 1], [2, "Борис Иванов", "Казань", "boris@gmail.com", "2024-02-03", 0], [3, "Вера Смирнова", "Москва", null, "2024-02-20", 0], [4, "Глеб Орлов", "Тверь", "gleb@yandex.ru", "2024-03-11", 0], [5, "Дарья Лебедева", "Санкт-Петербург", "dasha@mail.ru", "2024-03-30", 1], [6, "Егор Козлов", "Казань", "egor@gmail.com", "2024-04-08", 0], [7, "Жанна Морозова", null, "zhanna@yandex.ru", "2024-04-25", 0], [8, "Игорь Соколов", "Москва", "igor@mail.ru", "2024-05-02", 0], [9, "Ксения Волкова", "Омск", null, "2024-05-19", 0], [10, "Лев Новиков", "Санкт-Петербург", "lev@gmail.com", "2024-06-07", 1], [11, "Мария Фёдорова", "Тверь", "maria@mail.ru", "2024-06-21", 0], [12, "Никита Белов", "Москва", "nikita@yandex.ru", "2024-07-04", 0], [14, "Новый", null, null, "2024-08-02", 0]], "expected_cols": ["id", "name", "city", "email", "registered", "vip"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнов