INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-18', 17, 'sql', 'Пополнить склад', 'Увеличьте остаток (stock) всех товаров с нулевым остатком до 20.', '-- Напишите запрос
', '', '{"check": "SELECT id, title, category, price, stock, brand FROM products ORDER BY id", "expected": [[1, "Ноутбук Air 13", "Электроника", 78000, 5, "Nova"], [2, "Смартфон S5", "Электроника", 45000, 12, "Nova"], [3, "Наушники Beat", "Электроника", 5200, 40, "Sonic"], [4, "Мышь Click", "Аксессуары", 1500, 80, "Sonic"], [5, "Клавиатура Type", "Аксессуары", 3900, 25, "Keyra"], [6, "Рюкзак City", "Аксессуары", 3200, 20, "Urbo"], [7, "Кофе зерновой", "Продукты", 890, 150, "Bean"], [8, "Чай зелёный", "Продукты", 420, 200, "Leaf"], [9, "Шоколад тёмный", "Продукты", 180, 300, "Cacao"], [10, "Книга SQL", "Книги", 1200, 30, "Prime"], [11, "Книга Python", "Книги", 1350, 18, "Prime"], [12, "Блокнот A5", "Канцелярия", 250, 500, null], [13, "Подарочная карта", "Прочее", 1000, 999, null]], "expected_cols": ["id", "title", "category", "price", "stock", "brand"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Пете