INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-27', 26, 'sql', 'DELETE одной строки', 'Удалите клиента с id 12.', 'DELETE FROM customers
