INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-34', 33, 'sql', 'UPDATE RETURNING', 'Поднимите цену товара 4 на 100 и верните id и новую цену: UPDATE … RETURNING id, price.', '-- Напишите запрос
