,''Ева Миронова'',4,NULL,170000,''2021-10-01'',''eva@corp.ru'',''+7 482 444-44-41'',''lead''),\n (12,''Артём Исаев'',4,11,80000,''2024-03-18'',''artem@corp.ru'',NULL,''junior''),\n (13,''Вера Жукова'',4,11,85000,''2023-12-04'',''vera.z@corp.ru'',''+7 482 444-44-43'',''junior''),\n (14,''Тимур Рахимов'',NULL,NULL,130000,''2024-05-06'',''timur@corp.ru'',NULL,''middle''),\n (15,''Юлия Седова'',2,5,175000,''2020-09-21'',''yulia@corp.ru'',''+7 843 222-22-25'',''senior'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-44', 43, 'sql', 'HR: новый отдел', 'База HR. Добавьте отдел id 6 ''Аналитика'' (город ''Москва'') и сотрудника id 16 ''Дарья Ким'' (отдел 6, без начальника, salary 140000, hired ''2024-08-01'', email ''daria@corp.ru'', без телефона, grade ''middle'').', '-- Напишите запрос
', '', '{"check": "SELECT ''d'' AS t, id, name FROM departments WHERE id = 6 UNION ALL SELECT ''e'', id, name FROM employees WHERE id = 16 ORDER BY 1", "expected": [["d", 6, "Аналитика"], ["e", 16, "Дарья Ким"]], "expected_cols": ["t", "id", "name"], "ordered": true, "setup": "CREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  dept_id INTEGER REFERENCES departments(id),\n  boss_id INTEGER REFERENCES employees(id),\n  salary INTEGER NOT NULL,\n  hired TEXT NOT NULL,\n  email TEXT NOT NULL,\n  phone TEXT,\n  grade TEXT NOT NULL\n);\nINSERT INTO departments VALUES\n (1,''Разработка'',''Москва''),(2,''Продажи'',''Казань''),(3,''Бухгалтерия'',''Москва''),\n (4,''Поддержка'',''Тверь''),(5,''Исследования'',''Омск'');\nINSERT INTO employees VALUES\n (1,''Ольга Громова'',1,NULL,320000,''2019-03-01'',''olga@corp.ru'',''+7 495 111-11-11'',''lead''),\n (2,''Игорь Беляев'',1,1,210000,''2020-06-15'',''igor.b@corp.ru'',''+7 495 111-11-12'',''senior''),\n (3,''Мария Орлова'',1,1,190000,''2021-01-11'',''maria@corp.ru'',NULL,''middle''),\n (4,''Пётр Зуев'',1,2,120000,''2023-09-04'',''petr@corp.ru'',''+7 495 111-11-14'',''junior''),\n (5,''Нина Белова'',2,NULL,280000,''2018-11-20'',''nina@corp.ru'',''+7 843 222-22-21'',''lead''),\n (6,''Олег Савин'',2,5,150000,''2022-02-14'',''oleg@corp.ru'',''+7 843 222-22-22'',''middle''),\n (7,''Анна Крылова'',2,5,150000,''2022-08-01'',''anna.k@corp.ru'',NULL,''middle''),\n (8,''Сергей Ким'',2,5,95000,''2024-01-09'',''sergey@corp.ru'',''+7 843 222-22-24'',''junior''),\n (9,''Лидия Фомина'',3,NULL,200000,''2017-05-25'',''lidia@corp.ru'',''+7 495 333-33-31'',''lead''),\n (10,''Роман Дьяков'',3,9,110000,''2023-03-13'',''roman@corp.ru'',''+7 495 333-33-32'',''middle''),\n (11,''Ева Миронова'',4,NULL,170000,''2021-10-01'',''eva@corp.ru'',''+7 482 444-44-41'',''lead''),\n (12,''Артём Исаев'',4,11,80000,''2024-03-18'',''artem@corp.ru'',NULL,''junior''),\n (13,''Вера Жукова'',4,11,85000,''2023-12-04'',''vera.z@corp.ru'',''+7 482 444-44-43'',''junior''),\n (14,''Тимур Рахимов'',NULL,NULL,130000,''2024-05-06'',''timur@corp.ru'',NULL,''middle''),\n (15,''Юлия Седова'',2,5,175000,''2020-09-21'',''yulia@corp.ru'',''+7 843 222-22-25'',''senior'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-45', 44, 'sql', 'Школа: оценка', 'Школьная база. Выставьте оценку 4 всем записям 2024 года с пустой оценкой (score IS NULL).', '-- Напишите запрос
', '', '{"check": "SELECT student_id, course_id, year, score FROM enrollments ORDER BY student_id, course_id, year", "expected": [[1, 1, 2023, 4], [1, 1, 2024, 5], [1, 3, 2024, 5], [1, 4, 2024, 4], [2, 1, 2023, 3], [2, 1, 2024, 3], [2, 2, 2024, 4], [2, 3, 2024, 4], [3, 1, 2024, 4], [3, 3, 2023, 5], [3, 4, 2024, 5], [3, 5, 2024, 3], [4, 1, 2024, 4], [4, 2, 2024, 5], [4, 3, 2024, 5], [5, 1, 2024, 5], [5, 2, 2024, 4], [5, 5, 2024, 4], [6, 3, 2024, 3], [6, 4, 2024, 3], [7, 1, 2024, 4], [7, 2, 2024, 3], [7, 3, 2024, 5], [8, 4, 2024, 5], [8, 5, 2024, 4], [9, 1, 2024, 5], [9, 3, 2024, 4], [10, 2, 2024, 4], [10, 4, 2024, 4]], "expected_cols": ["student_id", "course_id", "year", "score"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-46', 45, 'sql', 'Школа: новая запись', 'Школьная база. Запишите ученика 10 на курс 3 в 2024 году без оценки (score NULL).', '-- Напишите запрос
', '', '{"check": "SELECT student_id, course_id, score, year FROM enrollments WHERE student_id = 10 ORDER BY course_id", "expected": [[10, 2, null, 2024], [10, 3, null, 2024], [10, 4, 4, 2024]], "expected_cols": ["student_id", "course_id", "score", "year"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 8, 's08-47', 46, 'sql', 'Фильмы: рейтинг', 'База фильмов. Установите фильму ''Неизвестный фильм'' рейтинг 6.5 и бюджет 10.', '-- Напишите запрос
', '', '{"check": "SELECT id, title, rating, budget FROM movies WHERE id = 13", "expected": [[13, "Неизвестный фильм", 6.5, 10]], "expected_cols": ["id", "title", "rating", "budget"], "setup": "CREATE TABLE directors (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  country TEXT NOT NULL\n);\nCREATE TABLE movies (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  genre TEXT NOT NULL,\n  rating REAL,\n  budget INTEGER,\n  director_id INTEGER REFERENCES directors(id)\n);\nINSERT INTO directors VALUES\n (1,''Кристофер Нолан'',''Великобритания''),(2,''Хаяо Миядзаки'',''Япония''),(3,''Андрей Звягинцев'',''Россия''),\n (4,''Грета Гервиг'',''США''),(5,''Дени Вильнёв'',''Канада'');\nINSERT INTO movies VALUES\n (1,''Начало'',2010,''фантастика'',8.8,160,1),(2,''Интерстеллар'',2014,''фантастика'',8.7,165,1),\n (3,''Тёмный рыцарь'',2008,''боевик'',9.0,185,1),(4,''Унесённые призраками'',2001,''анимация'',8.6,19,2),\n (5,''Ходячий замок'',2004,''анимация'',8.2,24,2),(6,''Ветер крепчает'',2013,''анимация'',7.8,30,2),\n (7,''Левиафан'',2014,''драма'',7.6,4,3),(8,''Нелюбовь'',2017,''драма'',7.7,5,3),\n (9,''Барби'',2023,''комедия'',6.9,145,4),(10,''Маленькие женщины'',2019,''драма'',7.8,40,4),\n (11,''Дюна'',2021,''фантастика'',8.0,165,5),(12,''Прибытие'',2016,''фантастика'',7.9,47,5),\n (13,''Неизвестный фильм'',2022,''драма'',NULL,NULL,NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-01', 0, 'sql', 'Первая таблица', 'Создайте таблицу tags: id (целое, первичный ключ) и name (текст). Итог проверяется по структуре таблицы.', 'CREATE TABLE tags (
  id ...,
  name ...
);
', 'CREATE TABLE имя (столбец тип, столбец тип, …);', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''tags'') ORDER BY cid", "expected": [["id", "INTEGER", 0, null, 1], ["name", "TEXT", 0, null, 0]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-02', 1, 'sql', 'Типы столбцов', 'Создайте таблицу items: id INTEGER PRIMARY KEY, title TEXT, price REAL, stock INTEGER.', '-- Напишите запрос
', '', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''items'') ORDER BY cid", "expected": [["id", "INTEGER", 0, null, 1], ["title", "TEXT", 0, null, 0], ["price", "REAL", 0, null, 0], ["stock", "INTEGER", 0, null, 0]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-03', 2, 'sql', 'NOT NULL', 'Создайте таблицу users: id INTEGER PRIMARY KEY, email TEXT NOT NULL, nickname TEXT (необязательный).', '-- Напишите запрос
', 'NOT NULL запрещает пустые значения.', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''users'') ORDER BY cid", "expected": [["id", "INTEGER", 0, null, 1], ["email", "TEXT", 1, null, 0], ["nickname", "TEXT", 0, null, 0]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-04', 3, 'sql', 'DEFAULT', 'Создайте таблицу tasks: id INTEGER PRIMARY KEY, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT ''new'', priority INTEGER DEFAULT 3.', '-- Напишите запрос
', '', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''tasks'') ORDER BY cid", "expected": [["id", "INTEGER", 0, null, 1], ["title", "TEXT", 1, null, 0], ["status", "TEXT", 1, "''new''", 0], ["priority", "INTEGER", 0, "3", 0]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-05', 4, 'sql', 'DEFAULT в действии', 'Создайте таблицу tasks (как в предыдущем задании), добавьте строку (title = ''написать отчёт'') без status и priority и убедитесь, что подставились значения по умолчанию.', '-- Напишите запрос
', '', '{"check": "SELECT id, title, status, priority FROM tasks", "expected": [[1, "написать отчёт", "new", 3]], "expected_cols": ["id", "title", "status", "priority"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-06', 5, 'sql', 'Текстовый ключ', 'Создайте таблицу countries: code TEXT PRIMARY KEY (например, ''RU''), name TEXT NOT NULL.', '-- Напишите запрос
', '', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''countries'') ORDER BY cid", "expected": [["code", "TEXT", 0, null, 1], ["name", "TEXT", 1, null, 0]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-07', 6, 'sql', 'Составной ключ', 'Создайте таблицу wishlist: customer_id INTEGER, product_id INTEGER, PRIMARY KEY (customer_id, product_id). Составной ключ запрещает повторы пары.', '-- Напишите запрос
', '', '{"check": "SELECT name, type, \"notnull\", dflt_value, pk FROM pragma_table_info(''wishlist'') ORDER BY cid", "expected": [["customer_id", "INTEGER", 0, null, 1], ["product_id", "INTEGER", 0, null, 2]], "expected_cols": ["name", "type", "notnull", "dflt_value", "pk"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-08', 7, 'sql', 'UNIQUE', 'Создайте таблицу accounts: id INTEGER PRIMARY KEY, login TEXT NOT NULL UNIQUE. Затем INSERT OR IGNORE двух строк с одинаковым login ''anna'' — вторая будет пропущена.', '-- Напишите запрос
', 'OR IGNORE молча пропускает строку, нарушающую ограничение.', '{"check": "SELECT id, login FROM accounts", "expected": [[1, "anna"]], "expected_cols": ["id", "login"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-09', 8, 'sql', 'CHECK', 'Создайте таблицу goods: id INTEGER PRIMARY KEY, title TEXT, price INTEGER CHECK (price >= 0). Вставьте через INSERT OR IGNORE строки (''a'', 100) и (''b'', -5); вторая нарушит CHECK.', '-- Напишите запрос
', '', '{"check": "SELECT id, title, price FROM goods", "expected": [[1, "a", 100]], "expected_cols": ["id", "title", "price"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-10', 9, 'sql', 'CHECK со списком', 'Создайте таблицу orders2: id INTEGER PRIMARY KEY, status TEXT NOT NULL CHECK (status IN (''new'', ''paid'', ''shipped'')). Вставьте через INSERT OR IGNORE статусы ''paid'' и ''lost'' — последний будет отвергнут.', '-- Напишите запрос
', '', '{"check": "SELECT id, status FROM orders2", "expected": [[1, "paid"]], "expected_cols": ["id", "status"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-11', 10, 'sql', 'NOT NULL в действии', 'Создайте таблицу people: id INTEGER PRIMARY KEY, name TEXT NOT NULL. INSERT OR IGNORE двух строк: (''Анна'') и (NULL). Останется одна.', '-- Напишите запрос
', '', '{"check": "SELECT id, name FROM people", "expected": [[1, "Анна"]], "expected_cols": ["id", "name"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-12', 11, 'sql', 'Составной UNIQUE', 'Создайте таблицу slots: room TEXT, hour INTEGER, UNIQUE (room, hour). Вставьте через INSERT OR IGNORE (''A'', 9), (''A'', 10), (''A'', 9), (''B'', 9) — повтор пары будет отвергнут.', '-- Напишите запрос
', '', '{"check": "SELECT room, hour FROM slots ORDER BY room, hour", "expected": [["A", 9], ["A", 10], ["B", 9]], "expected_cols": ["room", "hour"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-13', 12, 'sql', 'Внешний ключ', 'Создайте таблицу reviews: id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), stars INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5), body TEXT. Итог проверяется по внешним ключам таблицы.', '-- Напишите запрос
', 'REFERENCES таблица(столбец) объявляет внешний ключ.', '{"check": "SELECT \"table\", \"from\", \"to\" FROM pragma_foreign_key_list(''reviews'')", "expected": [["products", "product_id", "id"]], "expected_cols": ["table", "from", "to"], "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-14', 13, 'sql', 'Два внешних ключа', 'Создайте таблицу favorites: customer_id INTEGER NOT NULL REFERENCES customers(id), product_id INTEGER NOT NULL REFERENCES products(id), PRIMARY KEY (customer_id, product_id).', '-- Напишите запрос
', '', '{"check": "SELECT \"from\", \"table\", \"to\" FROM pragma_foreign_key_list(''favorites'') ORDER BY \"from\"", "expected": [["customer_id", "customers", "id"], ["product_id", "products", "id"]], "expected_cols": ["from", "table", "to"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''