INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-27', 26, 'sql', 'Сводная таблица', 'Создайте таблицу sales_by_status(status, n, revenue) из запроса: число заказов и сумма по статусам (используйте GROUP BY status).', '-- Напишите запрос
', '', '{"check": "SELECT status, n, revenue FROM sales_by_status ORDER BY status", "expected": [["cancelled", 2, 7100], ["new", 4, 86770], ["paid", 6, 123040], ["shipped", 8, 140330]], "expected_cols": ["status", "n", "revenue"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-28', 27, 'sql', 'Временная таблица', 'Создайте временную таблицу top_products (CREATE TEMP TABLE … AS SELECT …) с тремя самыми дорогими товарами: title, price.', '-- Напишите запрос
', '', '{"check": "SELECT title, price FROM top_products ORDER BY price DESC", "expected": [["Ноутбук Air 13", 78000], ["Смартфон S5", 45000], ["Наушники Beat", 5200]], "expected_cols": ["title", "price"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-29', 28, 'sql', 'Вычисляемый столбец', 'Создайте таблицу lines: qty INTEGER, price INTEGER, total INTEGER GENERATED ALWAYS AS (qty * price) STORED. Вставьте (2, 150) и (3, 40); total посчитается сам.', '-- Напишите запрос
', '', '{"check": "SELECT qty, price, total FROM lines ORDER BY qty", "expected": [[2, 150, 300], [3, 40, 120]], "expected_cols": ["qty", "price", "total"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-30', 29, 'sql', 'Аффинность типов', 'SQLite приводит значения к типу столбца (аффинность). Создайте таблицу t(a INTEGER), вставьте ''123'' (строкой) и ''abc''. Выведите typeof(a) для обеих строк по возрастанию rowid.', '-- Напишите запрос
', '''123'' превратится в число, а ''abc'' останется текстом.', '{"check": "SELECT a, typeof(a) AS t FROM t ORDER BY rowid", "expected": [[123, "integer"], ["abc", "text"]], "expected_cols": ["a", "t"], "ordered": true, "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-31', 30, 'sql', 'Подробный каталог', 'Выведите названия таблиц и число столбцов в каждой: sqlite_master JOIN pragma_table_info(name); столбцы name, cols; по name.', '-- Напишите запрос
', '', '{"expected": [["customers", 6], ["order_items", 4], ["orders", 5], ["products", 6]], "expected_cols": ["name", "cols"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-32', 31, 'sql', 'Пересоздать с новым ограничением', 'В SQLite ограничение нельзя добавить командой ALTER — таблицу пересоздают. Создайте goods_new(id INTEGER PRIMARY KEY, title TEXT NOT NULL, price INTEGER NOT NULL CHECK (price > 0)), перенесите в неё id, title, price из products, удалите products и переименуйте goods_new в products.', '-- Напишите запрос
', '', '{"check": "SELECT COUNT(*) AS n, (SELECT sql LIKE ''%CHECK%'' FROM sqlite_master WHERE name = ''products'') AS has_check FROM products", "expected": [[13, 1]], "expected_cols": ["n", "has_check"], "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'',''Тверь'',''maria@mail.ru'',''2024-06-21'',0),\n (12,''Никита Белов'',''Москва'',''nikita@yandex.ru'',''2024-07-04'',0);\nINSERT INTO products VALUES\n (1,''Ноутбук Air 13'',''Электроника'',78000,5,''Nova''),\n (2,''Смартфон S5'',''Электроника'',45000,12,''Nova''),\n (3,''Наушники Beat'',''Электроника'',5200,40,''Sonic''),\n (4,''Мышь Click'',''Аксессуары'',1500,80,''Sonic''),\n (5,''Клавиатура Type'',''Аксессуары'',3900,25,''Keyra''),\n (6,''Рюкзак City'',''Аксессуары'',3200,0,''Urbo''),\n (7,''Кофе зерновой'',''Продукты'',890,150,''Bean''),\n (8,''Чай зелёный'',''Продукты'',420,200,''Leaf''),\n (9,''Шоколад тёмный'',''Продукты'',180,300,''Cacao''),\n (10,''Книга SQL'',''Книги'',1200,30,''Prime''),\n (11,''Книга Python'',''Книги'',1350,18,''Prime''),\n (12,''Блокнот A5'',''Канцелярия'',250,500,NULL),\n (13,''Подарочная карта'',''Прочее'',1000,999,NULL);\nINSERT INTO orders (id, customer_id, created, status) VALUES\n (1,1,''2024-02-01'',''shipped''),(2,1,''2024-03-15'',''shipped''),(3,2,''2024-03-02'',''paid''),\n (4,2,''2024-04-10'',''cancelled''),(5,3,''2024-03-05'',''shipped''),(6,4,''2024-03-20'',''new''),\n (7,5,''2024-04-02'',''shipped''),(8,5,''2024-04-18'',''paid''),(9,5,''2024-05-07'',''shipped''),\n (10,6,''2024-05-01'',''paid''),(11,8,''2024-05-15'',''new''),(12,8,''2024-06-03'',''shipped''),\n (13,10,''2024-06-10'',''paid''),(14,10,''2024-06-25'',''shipped''),(15,11,''2024-07-01'',''cancelled''),\n (16,12,''2024-07-08'',''paid''),(17,1,''2024-07-12'',''new''),(18,2,''2024-07-20'',''shipped''),\n (19,3,''2024-07-22'',''paid''),(20,5,''2024-07-30'',''new'');\nINSERT INTO order_items VALUES\n (1,1,1,78000),(1,4,1,1500),(2,3,1,5200),(3,2,1,45000),(3,3,2,5200),(4,5,1,3900),\n (5,7,2,890),(5,8,3,420),(6,10,1,1200),(6,11,1,1350),(7,2,1,45000),(8,3,1,5200),\n (8,4,2,1500),(9,12,10,250),(10,9,5,180),(10,8,2,420),(11,1,1,78000),(12,7,1,890),\n (13,2,1,45000),(13,4,1,1500),(14,10,2,1200),(15,6,1,3200),(16,5,1,3900),(16,3,1,5200),\n (17,11,1,1350),(17,10,1,1200),(18,9,10,180),(19,8,5,420),(20,7,3,890),(20,12,4,250);\nUPDATE orders SET total = (SELECT SUM(qty * price) FROM order_items WHERE order_id = orders.id);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-33', 32, 'sql', 'Разделить таблицу', 'В таблице flat(order_id, customer, city, product, price) данные дублируются. Создайте таблицу cust(customer, city) без повторов и prod(product, price) без повторов (CREATE TABLE … AS SELECT DISTINCT …).', '-- Напишите запрос
', '', '{"check": "SELECT ''cust'' AS t, customer AS a, city AS b FROM cust UNION ALL SELECT ''prod'', product, price FROM prod ORDER BY 1, 2", "expected": [["cust", "Анна", "Москва"], ["cust", "Борис", "Казань"], ["prod", "Кофе", 300], ["prod", "Сыр", 350], ["prod", "Чай", 100]], "expected_cols": ["t", "a", "b"], "ordered": true, "setup": "CREATE TABLE flat (order_id INTEGER, customer TEXT, city TEXT, product TEXT, price INTEGER);\nINSERT INTO flat VALUES (1,''Анна'',''Москва'',''Чай'',100),(2,''Анна'',''Москва'',''Кофе'',300),(3,''Борис'',''Казань'',''Чай'',100),(4,''Борис'',''Казань'',''Сыр'',350);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-34', 33, 'sql', 'Структура таблицы', 'База HR. Выведите для таблицы employees имя, тип и признак notnull каждого столбца в порядке объявления: SELECT name, type, "notnull" FROM pragma_table_info(''employees'').', '-- Напишите запрос
', '', '{"expected": [["id", "INTEGER", 0], ["name", "TEXT", 1], ["dept_id", "INTEGER", 0], ["boss_id", "INTEGER", 0], ["salary", "INTEGER", 1], ["hired", "TEXT", 1], ["email", "TEXT", 1], ["phone", "TEXT", 0], ["grade", "TEXT", 1]], "expected_cols": ["name", "type", "notnull"], "ordered": true, "setup": "CREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  dept_id INTEGER REFERENCES departments(id),\n  boss_id INTEGER REFERENCES employees(id),\n  salary INTEGER NOT NULL,\n  hired TEXT NOT NULL,\n  email TEXT NOT NULL,\n  phone TEXT,\n  grade TEXT NOT NULL\n);\nINSERT INTO departments VALUES\n (1,''Разработка'',''Москва''),(2,''Продажи'',''Казань''),(3,''Бухгалтерия'',''Москва''),\n (4,''Поддержка'',''Тверь''),(5,''Исследования'',''Омск'');\nINSERT INTO employees VALUES\n (1,''Ольга Громова'',1,NULL,320000,''2019-03-01'',''olga@corp.ru'',''+7 495 111-11-11'',''lead''),\n (2,''Игорь Беляев'',1,1,210000,''2020-06-15'',''igor.b@corp.ru'',''+7 495 111-11-12'',''senior''),\n (3,''Мария Орлова'',1,1,190000,''2021-01-11'',''maria@corp.ru'',NULL,''middle''),\n (4,''Пётр Зуев'',1,2,120000,''2023-09-04'',''petr@corp.ru'',''+7 495 111-11-14'',''junior''),\n (5,''Нина Белова'',2,NULL,280000,''2018-11-20'',''nina@corp.ru'',''+7 843 222-22-21'',''lead''),\n (6,''Олег Савин'',2,5,150000,''2022-02-14'',''oleg@corp.ru'',''+7 843 222-22-22'',''middle''),\n (7,''Анна Крылова'',2,5,150000,''2022-08-01'',''anna.k@corp.ru'',NULL,''middle''),\n (8,''Сергей Ким'',2,5,95000,''2024-01-09'',''sergey@corp.ru'',''+7 843 222-22-24'',''junior''),\n (9,''Лидия Фомина'',3,NULL,200000,''2017-05-25'',''lidia@corp.ru'',''+7 495 333-33-31'',''lead''),\n (10,''Роман Дьяков'',3,9,110000,''2023-03-13'',''roman@corp.ru'',''+7 495 333-33-32'',''middle''),\n (11,''Ева Миронова'',4,NULL,170000,''2021-10-01'',''eva@corp.ru'',''+7 482 444-44-41'',''lead''),\n (12,''Артём Исаев'',4,11,80000,''2024-03-18'',''artem@corp.ru'',NULL,''junior''),\n (13,''Вера Жукова'',4,11,85000,''2023-12-04'',''vera.z@corp.ru'',''+7 482 444-44-43'',''junior''),\n (14,''Тимур Рахимов'',NULL,NULL,130000,''2024-05-06'',''timur@corp.ru'',NULL,''middle''),\n (15,''Юлия Седова'',2,5,175000,''2020-09-21'',''yulia@corp.ru'',''+7 843 222-22-25'',''senior'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-35', 34, 'sql', 'Индексы таблицы', 'Создайте таблицу u(id INTEGER PRIMARY KEY, email TEXT UNIQUE, code TEXT UNIQUE) и выведите число её индексов (pragma_index_list) как n — каждое UNIQUE создаёт индекс.', '-- Напишите запрос
', '', '{"expected": [[2]], "expected_cols": ["n"], "setup": "\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-36', 35, 'sql', 'Школа: новая таблица', 'Школьная база. Создайте таблицу teachers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, subject TEXT) и добавьте двух преподавателей: ''Н. Крылова'' (Математика) и ''А. Беляев'' (Физика).', '-- Напишите запрос
', '', '{"check": "SELECT id, name, subject FROM teachers ORDER BY id", "expected": [[1, "Н. Крылова", "Математика"], [2, "А. Беляев", "Физика"]], "expected_cols": ["id", "name", "subject"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 9, 's09-37', 36, 'sql', 'Фильмы: жанры', 'База фильмов. Создайте справочник genres(name TEXT PRIMARY KEY) и заполните его различными жанрами из movies (INSERT … SELECT DISTINCT genre …).', '-- Напишите запрос
', '', '{"check": "SELECT name FROM genres ORDER BY name", "expected": [["анимация"], ["боевик"], ["драма"], ["комедия"], ["фантастика"]], "expected_cols": ["name"], "ordered": true, "setup": "CREATE TABLE directors (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  country TEXT NOT NULL\n);\nCREATE TABLE movies (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  genre TEXT NOT NULL,\n  rating REAL,\n  budget INTEGER,\n  director_id INTEGER REFERENCES directors(id)\n);\nINSERT INTO directors VALUES\n (1,''Кристофер Нолан'',''Великобритания''),(2,''Хаяо Миядзаки'',''Япония''),(3,''Андрей Звягинцев'',''Россия''),\n (4,''Грета Гервиг'',''США''),(5,''Дени Вильнёв'',''Канада'');\nINSERT INTO movies VALUES\n (1,''Начало'',2010,''фантастика'',8.8,160,1),(2,''Интерстеллар'',2014,''фантастика'',8.7,165,1),\n (3,''Тёмный рыцарь'',2008,''боевик'',9.0,185,1),(4,''Унесённые призраками'',2001,''анимация'',8.6,19,2),\n (5,''Ходячий замок'',2004,''анимация'',8.2,24,2),(6,''Ветер крепчает'',2013,''анимация'',7.8,30,2),\n (7,''Левиафан'',2014,''драма'',7.6,4,3),(8,''Нелюбовь'',2017,''драма'',7.7,5,3),\n (9,''Барби'',2023,''комедия'',6.9,145,4),(10,''Маленькие женщины'',2019,''драма'',7.8,40,4),\n (11,''Дюна'',2021,''фантастика'',8.0,165,5),(12,''Прибытие'',2016,''фантастика'',7.9,47,5),\n (13,''Неизвестный фильм'',2022,''драма'',NULL,NULL,NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 10, 's10-01', 0, 'sql', 'Простой CASE', 'Выведите id заказа и статус по-русски: ''new'' — ''новый'', ''paid'' — ''оплачен'', ''shipped'' — ''отправлен'', ''cancelled'' — ''отменён''. Столбцы id, status_ru; по id.', 'SELECT id,
  CASE status
    WHEN ''new'' THEN ...
  END AS status_ru
FROM orders
ORDER BY id;
', 'CASE выражение WHEN значение THEN результат … END', '{"expected": [[1, "отправлен"], [2, "отправлен"], [3, "оплачен"], [4, "отменён"], [5, "отправлен"], [6, "новый"], [7, "отправлен"], [8, "оплачен"], [9, "отправлен"], [10, "оплачен"], [11, "новый"], [12, "отправлен"], [13, "оплачен"], [14, "отправлен"], [15, "отменён"], [16, "оплачен"], [17, "новый"], [18, "отправлен"], [19, "оплачен"], [20, "новый"]], "expected_cols": ["id", "status_ru"], "ordered": true, "setup": "CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT,\n  email TEXT,\n  registered TEXT NOT NULL,\n  vip INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  category TEXT NOT NULL,\n  price INTEGER NOT NULL,\n  stock INTEGER NOT NULL,\n  brand TEXT\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER NOT NULL REFERENCES customers(id),\n  created TEXT NOT NULL,\n  status TEXT NOT NULL,\n  total INTEGER NOT NULL DEFAULT 0\n);\nCREATE TABLE order_items (\n  order_id INTEGER NOT NULL REFERENCES orders(id),\n  product_id INTEGER NOT NULL REFERENCES products(id),\n  qty INTEGER NOT NULL,\n  price INTEGER NOT NULL,\n  PRIMARY KEY (order_id, product_id)\n);\nINSERT INTO customers VALUES\n (1,''Анна Петрова'',''Москва'',''anna@mail.ru'',''2024-01-15'',1),\n (2,''Борис Иванов'',''Казань'',''boris@gmail.com'',''2024-02-03'',0),\n (3,''Вера Смирнова'',''Москва'',NULL,''2024-02-20'',0),\n (4,''Глеб Орлов'',''Тверь'',''gleb@yandex.ru'',''2024-03-11'',0),\n (5,''Дарья Лебедева'',''Санкт-Петербург'',''dasha@mail.ru'',''2024-03-30'',1),\n (6,''Егор Козлов'',''Казань'',''egor@gmail.com'',''2024-04-08'',0),\n (7,''Жанна Морозова'',NULL,''zhanna@yandex.ru'',''2024-04-25'',0),\n (8,''Игорь Соколов'',''Москва'',''igor@mail.ru'',''2024-05-02'',0),\n (9,''Ксения Волкова'',''Омск'',NULL,''2024-05-19'',0),\n (10,''Лев Новиков'',''Санкт-Петербург'',''lev@gmail.com'',''2024-06-07'',1),\n (11,''Мария Фёдорова'','