INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 11, 's11-41', 40, 'sql', 'HR: зарплата в тысячах', 'База HR. Выведите name и salary в тысячах с округлением вниз: salary / 1000 как k; по id.', '-- Напишите запрос
', '', '{"expected": [["Ольга Громова", 320], ["Игорь Беляев", 210], ["Мария Орлова", 190], ["Пётр Зуев", 120], ["Нина Белова", 280], ["Олег Савин", 150], ["Анна Крылова", 150], ["Сергей Ким", 95], ["Лидия Фомина", 200], ["Роман Дьяков", 110], ["Ева Миронова", 170], ["Артём Исаев", 80], ["Вера Жукова", 85], ["Тимур Рахимов", 130], ["Юлия Седова", 175]], "expected_cols": ["name", "k"], "ordered": true, "setup": "CREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  dept_id INTEGER REFERENCES departments(id),\n  boss_id INTEGER REFERENCES employees(id),\n  salary INTEGER NOT NULL,\n  hired TEXT NOT NULL,\n  email TEXT NOT NULL,\n  phone TEXT,\n  grade TEXT NOT NULL\n);\nINSERT INTO departments VALUES\n (1,''Разработка'',''Москва''),(2,''Продажи'',''Казань''),(3,''Бухгалтерия'',''Москва''),\n (4,''Поддержка'',''Тверь''),(5,''Исследования'',''Омск'');\nINSERT INTO employees VALUES\n (1,''Ольга Громова'',1,NULL,320000,''2019-03-01'',''olga@corp.ru'',''+7 495 111-11-11'',''lead''),\n (2,''Игорь Беляев'',1,1,210000,''2020-06-15'',''igor.b@corp.ru'',''+7 495 111-11-12'',''senior''),\n (3,''Мария Орлова'',1,1,190000,''2021-01-11'',''maria@corp.ru'',NULL,''middle''),\n (4,''Пётр Зуев'',1,2,120000,''2023-09-04'',''petr@corp.ru'',''+7 495 111-11-14'',''junior''),\n (5,''Нина Белова'',2,NULL,280000,''2018-11-20'',''nina@corp.ru'',''+7 843 222-22-21'',''lead''),\n (6,''Олег Савин'',2,5,150000,''2022-02-14'',''oleg@corp.ru'',''+7 843 222-22-22'',''middle''),\n (7,''Анна Крылова'',2,5,150000,''2022-08-01'',''anna.k@corp.ru'',NULL,''middle''),\n (8,''Сергей Ким'',2,5,95000,''2024-01-09'',''sergey@corp.ru'',''+7 843 222-22-24'',''junior''),\n (9,''Лидия Фомина'',3,NULL,200000,''2017-05-25'',''lidia@corp.ru'',''+7 495 333-33-31'',''lead''),\n (10,''Роман Дьяков'',3,9,110000,''2023-03-13'',''roman@corp.ru'',''+7 495 333-33-32'',''middle''),\n (11,''Ева Миронова'',4,NULL,170000,''2021-10-01'',''eva@corp.ru'',''+7 482 444-44-41'',''lead''),\n (12,''Артём Исаев'',4,11,80000,''2024-03-18'',''artem@corp.ru'',NULL,''junior''),\n (13,''Вера Жукова'',4,11,85000,''2023-12-04'',''vera.z@corp.ru'',''+7 482 444-44-43'',''junior''),\n (14,''Тимур Рахимов'',NULL,NULL,130000,''2024-05-06'',''timur@corp.ru'',NULL,''middle''),\n (15,''Юлия Седова'',2,5,175000,''2020-09-21'',''yulia@corp.ru'',''+7 843 222-22-25'',''senior'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 11, 's11-42', 41, 'sql', 'Школа: возраст', 'Школьная база. Выведите name и возраст на ''2024-09-01'' в целых годах: CAST((julianday(''2024-09-01'') - julianday(birth)) / 365.25 AS INTEGER) как age; по id.', '-- Напишите запрос
', '', '{"expected": [["Алёна Громова", 15], ["Богдан Сидоров", 14], ["Варвара Кузнецова", 15], ["Давид Попов", 16], ["Ева Васильева", 15], ["Фёдор Михайлов", 16], ["Галина Соколова", 17], ["Игнат Павлов", 16], ["Яна Тихонова", 17], ["Тимофей Орлов", 15]], "expected_cols": ["name", "age"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 11, 's11-43', 42, 'sql', 'Школа: номер класса', 'Школьная база. Выведите name и номер параллели (число в class) как grade: CAST(class AS INTEGER) — приведение берёт число из начала строки; по id.', '-- Напишите запрос
