', '', '{"expected": [["10А", 2], ["10Б", 1], ["11А", 2], ["11Б", 1], ["9А", 2], ["9Б", 2]], "expected_cols": ["class", "n"], "ordered": true, "setup": "CREATE TABLE students (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  class TEXT NOT NULL,\n  birth TEXT NOT NULL,\n  city TEXT NOT NULL\n);\nCREATE TABLE courses (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  teacher TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\nCREATE TABLE enrollments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  course_id INTEGER NOT NULL REFERENCES courses(id),\n  score INTEGER,\n  year INTEGER NOT NULL,\n  PRIMARY KEY (student_id, course_id, year)\n);\nINSERT INTO students VALUES\n (1,''Алёна Громова'',''9А'',''2009-04-12'',''Москва''),\n (2,''Богдан Сидоров'',''9А'',''2009-09-30'',''Казань''),\n (3,''Варвара Кузнецова'',''9Б'',''2009-01-25'',''Москва''),\n (4,''Давид Попов'',''10А'',''2008-06-18'',''Тверь''),\n (5,''Ева Васильева'',''10А'',''2008-11-03'',''Москва''),\n (6,''Фёдор Михайлов'',''10Б'',''2008-02-14'',''Омск''),\n (7,''Галина Соколова'',''11А'',''2007-07-07'',''Казань''),\n (8,''Игнат Павлов'',''11А'',''2007-12-21'',''Москва''),\n (9,''Яна Тихонова'',''11Б'',''2007-03-09'',''Тверь''),\n (10,''Тимофей Орлов'',''9Б'',''2009-08-15'',''Москва'');\nINSERT INTO courses VALUES\n (1,''Математика'',''Н. Крылова'',140),(2,''Физика'',''А. Беляев'',102),(3,''Информатика'',''М. Лебедев'',68),\n (4,''Литература'',''О. Миронова'',102),(5,''История'',''В. Жуков'',68),(6,''Химия'',''Е. Седова'',68);\nINSERT INTO enrollments VALUES\n (1,1,5,2024),(1,3,5,2024),(1,4,4,2024),(2,1,3,2024),(2,2,4,2024),(2,3,NULL,2024),\n (3,1,4,2024),(3,4,5,2024),(3,5,3,2024),(4,2,5,2024),(4,3,5,2024),(4,1,4,2024),\n (5,1,5,2024),(5,2,4,2024),(5,5,NULL,2024),(6,3,3,2024),(6,4,3,2024),(7,1,4,2024),\n (7,2,3,2024),(7,3,5,2024),(8,5,4,2024),(8,4,5,2024),(9,1,5,2024),(9,3,4,2024),\n (10,2,NULL,2024),(10,4,4,2024),(1,1,4,2023),(2,1,3,2023),(3,3,5,2023);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 12, 's12-42', 41, 'sql', 'Фильмы: по жанрам', 'База фильмов. Выведите genre, число фильмов n и средний рейтинг (ROUND до 2 знаков) avg_rating по жанрам; по n по убыванию, затем genre.', '-- Напишите запрос
', '', '{"expected": [["драма", 4, 7.7], ["фантастика", 4, 8.35], ["анимация", 3, 8.2], ["боевик", 1, 9.0], ["комедия", 1, 6.9]], "expected_cols": ["genre", "n", "avg_rating"], "ordered": true, "setup": "CREATE TABLE directors (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  country TEXT NOT NULL\n);\nCREATE TABLE movies (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  genre TEXT NOT NULL,\n  rating REAL,\n  budget INTEGER,\n  director_id INTEGER REFERENCES directors(id)\n);\nINSERT INTO directors VALUES\n (1,''Кристофер Нолан'',''Великобритания''),(2,''Хаяо Миядзаки'',''Япония''),(3,''Андрей Звягинцев'',''Россия''),\n (4,''Грета Гервиг'',''США''),(5,''Дени Вильнёв'',''Канада'');\nINSERT INTO movies VALUES\n (1,''Начало'',2010,''фантастика'',8.8,160,1),(2,''Интерстеллар'',2014,''фантастика'',8.7,165,1),\n (3,''Тёмный рыцарь'',2008,''боевик'',9.0,185,1),(4,''Унесённые призраками'',2001,''анимация'',8.6,19,2),\n (5,''Ходячий замок'',2004,''анимация'',8.2,24,2),(6,''Ветер крепчает'',2013,''анимация'',7.8,30,2),\n (7,''Левиафан'',2014,''драма'',7.6,4,3),(8,''Нелюбовь'',2017,''драма'',7.7,5,3),\n (9,''Барби'',2023,''комедия'',6.9,145,4),(10,''Маленькие женщины'',2019,''драма'',7.8,40,4),\n (11,''Дюна'',2021,''фантастика'',8.0,165,5),(12,''Прибытие'',2016,''фантастика'',7.9,47,5),\n (13,''Неизвестный фильм'',2022,''драма'',NULL,NULL,NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 12, 's12-43', 42, 'sql', 'Фильмы: режиссёры', 'База фильмов. Выведите name режиссёра и число его фильмов n; по n по убыванию, затем name.', '-- Напишите запрос
