INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 14, 's14-07', 6, 'sql', 'Цепочка CTE', 'Цепочка: items_sum (SUM(qty * price) по order_id) → big (заказы с суммой по позициям > 40000) → основной запрос выводит order_id, s по order_id.', '-- Напишите запрос
