INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-coalesce', 6, 'sql', 'COALESCE: пропуски в премии', 'Выведите имя и премию каждого сотрудника, а пропуск (NULL) в премии заменяйте нулём. Колонки: name, bonus; порядок по id.', '-- имя и премия (NULL → 0)
