INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-foreign-key', 10, 'sql', 'Внешний ключ', 'Создайте таблицу invoices: id — первичный ключ, customer_id — целое, обязательное и ссылается на customers(id), amount — целое. Столбцы — в этом порядке.', '-- таблица invoices с внешним ключом на customers
CREATE TABLE invoices (

);
