INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-inner-join', 11, 'sql', 'Соединение: клиент и заказ', 'Выведите имя клиента и дату заказа для всех оплаченных заказов (status = ''paid'') по возрастанию даты, при равенстве — по имени. Колонки: name, created.', '-- имя клиента и дата оплаченных заказов
