', 'GROUP BY customer_id HAVING COUNT(*) >= 2.', '{"expected": [[1, 2], [2, 2], [3, 3]], "expected_cols": ["customer_id", "n"], "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-revenue-by-category', 17, 'sql', 'Выручка по категориям', 'Посчитайте выручку по категориям товаров — сумму qty × price — только по оплаченным заказам. Колонки: category, revenue; порядок по убыванию выручки.', '-- выручка по категориям (paid)
SELECT
', 'Соедините order_items, orders и products; WHERE o.status = ''paid''; GROUP BY p.category.', '{"expected": [["tech", 159500], ["food", 5600], ["books", 2700]], "expected_cols": ["category", "revenue"], "ordered": true, "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-above-average', 18, 'sql', 'Скалярный подзапрос', 'Выведите названия товаров, цена которых выше средней цены всех товаров. Колонка title, порядок по id.', '-- товары дороже средней цены
SELECT
', 'Средняя цена — подзапрос в скобках: price > (SELECT AVG(price) FROM products).', '{"expected": [["Ноутбук"]], "expected_cols": ["title"], "ordered": true, "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-exists', 19, 'sql', 'EXISTS: есть оплаченный заказ', 'Выведите имена клиентов, у которых есть хотя бы один оплаченный заказ, через EXISTS. Колонка name, порядок по id.', '-- клиенты с оплаченным заказом
SELECT
', 'Коррелированный подзапрос: WHERE o.customer_id = c.id AND o.status = ''paid''.', '{"expected": [["Анна"], ["Борис"], ["Вера"], ["Дарья"]], "expected_cols": ["name"], "ordered": true, "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-cte-no-multiply', 20, 'sql', 'Свернуть до соединения', 'Для каждого оплаченного заказа выведите число позиций (items = сумма qty) и сумму платежей (paid_sum). Если соединить обе таблицы напрямую, суммы удвоятся: сначала сверните каждую ветку отдельно (WITH или подзапросы). Колонки: id, items, paid_sum; только заказы, по которым есть и позиции, и платежи; порядок по id.', '-- по оплаченным заказам: items и paid_sum без размножения строк
WITH
', 'Каждый CTE даёт одну строку на заказ; JOIN сворачивающих запросов уже не размножает строки.', '{"expected": [[1, 3, 70], [2, 4, 30], [4, 2, 205], [5, 3, 40]], "expected_cols": ["id", "items", "paid_sum"], "ordered": true, "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\nCREATE TABLE payments (order_id INTEGER NOT NULL REFERENCES orders(id), amount INTEGER NOT NULL);\nINSERT INTO payments VALUES (1,50),(1,20),(2,30),(4,100),(4,100),(4,5),(5,40);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-update-returning', 21, 'sql', 'UPDATE … RETURNING', 'Поднимите цену всех товаров категории ''tech'' на 10 % (в целых рублях: price = price * 11 / 10) и верните изменённые строки: id и новую цену (колонки: id, price), по возрастанию id.', '-- поднять цену tech на 10 % и вернуть id, price
UPDATE
', 'RETURNING id, price в конце UPDATE возвращает изменённые строки. Не забудьте WHERE category = ''tech''.', '{"expected": [[1, 77000], [2, 1650], [6, 5500]], "expected_cols": ["id", "price"], "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-upsert', 22, 'sql', 'UPSERT: ON CONFLICT', 'Склад stock(id, qty). Придёт поставка: товару 2 — ещё 7 штук, товару 3 — 4 штуки (его на складе пока нет). Одним INSERT … ON CONFLICT выполните обе вставки так, чтобы для существующего товара количество увеличилось. Итог проверяется по таблице.', '-- поставка: (2, 7) и (3, 4) через INSERT ... ON CONFLICT
INSERT INTO stock (id, qty) VALUES
', 'ON CONFLICT (id) DO UPDATE SET qty = qty + excluded.qty; excluded — вставляемая строка.', '{"check": "SELECT id, qty FROM stock ORDER BY id", "expected": [[1, 10], [2, 12], [3, 4]], "expected_cols": ["id", "qty"], "ordered": true, "setup": "CREATE TABLE stock (id INTEGER PRIMARY KEY, qty INTEGER NOT NULL);\nINSERT INTO stock VALUES (1,10),(2,5);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-delete-check', 23, 'sql', 'Безопасное удаление', 'Удалите отменённые заказы (status = ''cancelled'') вместе с их позициями: сначала позиции, потом сами заказы. Итог проверяется по числу строк в orders и order_items.', '-- удалить cancelled-заказы и их позиции
DELETE
', 'Порядок важен из-за внешнего ключа: сначала order_items с подзапросом по orders, затем orders.', '{"check": "SELECT (SELECT COUNT(*) FROM orders), (SELECT COUNT(*) FROM order_items)", "expected": [[7, 13]], "expected_cols": ["(SELECT COUNT(*) FROM orders)", "(SELECT COUNT(*) FROM order_items)"], "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 17, 'd1-case-when', 24, 'sql', 'CASE: ценовые категории', 'Для каждого товара выведите название и ценовую категорию: ''дорого'' при цене от 5000, ''средне'' от 1000 до 4999, иначе ''дёшево''. Колонки: title, tier; порядок по id.', '-- название и категория цены
SELECT
', 'CASE WHEN … THEN … WHEN … THEN … ELSE … END; ветви проверяются сверху вниз.', '{"expected": [["Ноутбук", "дорого"], ["Мышь", "средне"], ["Книга SQL", "дёшево"], ["Кофе", "дёшево"], ["Чай", "дёшево"], ["Наушники", "дорого"]], "expected_cols": ["title", "tier"], "ordered": true, "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, PRIMARY KEY (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-transfer', 0, 'sql', 'Перевод в одной транзакции', 'Переведите 30 рублей со счёта 1 на счёт 2 в одной транзакции (BEGIN … COMMIT). Итог проверяется по балансам.', '-- перевод 30 со счёта 1 на счёт 2
BEGIN;
', 'BEGIN; два UPDATE; COMMIT; — обе операции фиксируются разом.', '{"check": "SELECT id, bal FROM acc ORDER BY id", "expected": [[1, 70], [2, 80], [3, 0]], "expected_cols": ["id", "bal"], "ordered": true, "setup": "CREATE TABLE acc (id INTEGER PRIMARY KEY, owner TEXT NOT NULL, bal INTEGER NOT NULL CHECK (bal >= 0));\nINSERT INTO acc VALUES (1,''Анна'',100),(2,''Борис'',50),(3,''Вера'',0);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-conditional-debit', 1, 'sql', 'Списание, только если хватает', 'Сначала попытайтесь списать 150 со счёта 1 (там 100) — списание не должно произойти и не должно вызывать ошибку CHECK: защитите UPDATE условием. Затем спишите 80 с того же счёта. Итог проверяется по балансам.', '-- списать 150 (не хватает) и затем 80
', 'Условие bal >= сумма в WHERE: недостаточный остаток — 0 затронутых строк, а не ошибка.', '{"check": "SELECT id, bal FROM acc ORDER BY id", "expected": [[1, 20], [2, 50], [3, 0]], "expected_cols": ["id", "bal"], "ordered": true, "setup": "CREATE TABLE acc (id INTEGER PRIMARY KEY, owner TEXT NOT NULL, bal INTEGER NOT NULL CHECK (bal >= 0));\nINSERT INTO acc VALUES (1,''Анна'',100),(2,''Борис'',50),(3,''Вера'',0);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-atomic-update', 2, 'sql', 'Атомарное обновление вместо чтения', 'Начислите счёту 2 два бонуса по 10 и 15 рублей двумя UPDATE, в каждом — арифметика прямо в базе (bal = bal + …), без предварительных SELECT.', '-- два начисления арифметикой в базе
', 'UPDATE acc SET bal = bal + 10 WHERE id = 2; — чтение и запись в одном запросе.', '{"check": "SELECT bal FROM acc WHERE id = 2", "expected": [[75]], "expected_cols": ["bal"], "setup": "CREATE TABLE acc (id INTEGER PRIMARY KEY, owner TEXT NOT NULL, bal INTEGER NOT NULL CHECK (bal >= 0));\nINSERT INTO acc VALUES (1,''Анна'',100),(2,''Борис'',50),(3,''Вера'',0);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-savepoint', 3, 'sql', 'SAVEPOINT и частичный откат', 'В одной транзакции: вставьте запись ''start'', поставьте точку сохранения s1, вставьте ''oops'', откатитесь к s1, вставьте ''finish'' и зафиксируйте. В итоге в log должны остаться ''start'' и ''finish''.', '-- start, savepoint, oops, rollback to, finish
BEGIN;
', 'SAVEPOINT s1; … ROLLBACK TO s1; откат не закрывает транзакцию — дальше можно продолжать и делать COMMIT.', '{"check": "SELECT msg FROM log ORDER BY id", "expected": [["start"], ["finish"]], "expected_cols": ["msg"], "ordered": true, "setup": "CREATE TABLE log (id INTEGER PRIMARY KEY, msg TEXT NOT NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-optimistic', 4, 'sql', 'Оптимистичная проверка версии', 'Два редактора прочитали документ 7 при ver = 1. Первый сохраняет текст ''первый'', второй — ''второй'': оба обновляют с условием ver = 1 и увеличивают ver. Выполните оба UPDATE подряд: второй не должен ничего изменить. Итог проверяется по таблице.', '-- два UPDATE с проверкой версии
', 'В WHERE: id = 7 AND ver = 1; после первого обновления ver = 2, поэтому второе условие ложно.', '{"check": "SELECT body, ver FROM doc", "expected": [["первый", 2]], "expected_cols": ["body", "ver"], "setup": "CREATE TABLE doc (id INTEGER PRIMARY KEY, body TEXT NOT NULL, ver INTEGER NOT NULL);\nINSERT INTO doc VALUES (7,''v1'',1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-idempotent', 5, 'sql', 'Идемпотентная обработка платежа', 'Платёж p-100 на 500 рублей пришёл дважды (повтор после таймаута). Вставьте его двумя командами INSERT так, чтобы повтор был проигнорирован, а не вызвал ошибку: в таблице должна остаться одна строка.', '-- платёж p-100 дважды, но обработан один раз
', 'Уникальный ключ + INSERT OR IGNORE (или ON CONFLICT DO NOTHING) делают повтор безвредным.', '{"check": "SELECT payment_id, amount FROM payments", "expected": [["p-100", 500]], "expected_cols": ["payment_id", "amount"], "setup": "CREATE TABLE payments (payment_id TEXT PRIMARY KEY, amount INTEGER NOT NULL);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-write-skew', 6, 'sql', 'Перекос записи: дежурные врачи', 'Правило: на дежурстве всегда хотя бы один врач. Снимите с дежурства Анну, а затем Бориса — каждым UPDATE, в условии которого проверяется, что после снятия останется кто-то ещё (проверка и изменение в одном запросе). Второе снятие не должно сработать.', '-- снять Анну, затем Бориса с сохранением инварианта
', 'Условие (SELECT COUNT(*) … WHERE on_call = 1) > 1 внутри самого UPDATE: проверка и запись неделимы.', '{"check": "SELECT name, on_call FROM doctors ORDER BY name", "expected": [["Анна", 0], ["Борис", 1]], "expected_cols": ["name", "on_call"], "ordered": true, "setup": "CREATE TABLE doctors (name TEXT PRIMARY KEY, on_call INTEGER NOT NULL);\nINSERT INTO doctors VALUES (''Анна'',1),(''Борис'',1);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-queue-claim', 7, 'sql', 'Захват задачи из очереди', 'Два воркера по очереди забирают задачи. Каждый выполняет один UPDATE: переводит самую раннюю задачу со статусом ''new'' в ''taken'' и возвращает её id (RETURNING). Выполните две такие команды подряд; итог проверяется по таблице.', '-- два захвата самой ранней задачи new
', 'Выбор и захват — один UPDATE с подзапросом MIN(id): задача не достанется двум воркерам.', '{"check": "SELECT id, status FROM jobs ORDER BY id", "expected": [[1, "taken"], [2, "taken"], [3, "new"]], "expected_cols": ["id", "status"], "ordered": true, "setup": "CREATE TABLE jobs (id INTEGER PRIMARY KEY, status TEXT NOT NULL);\nINSERT INTO jobs VALUES (1,''new''),(2,''new''),(3,''new'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-ledger', 8, 'sql', 'Двойная запись: сумма равна нулю', 'Журнал проводок ledger(tx, account, amount): каждая транзакция должна давать в сумме 0. Найдите номера «битых» транзакций, у которых сумма не равна нулю, и саму сумму (колонки: tx, total).', '-- битые транзакции: сумма amount ≠ 0
SELECT
', 'GROUP BY tx HAVING SUM(amount) <> 0 — инвариант проверяется запросом.', '{"expected": [[3, 10]], "expected_cols": ["tx", "total"], "setup": "CREATE TABLE ledger (id INTEGER PRIMARY KEY, tx INTEGER NOT NULL, account TEXT NOT NULL, amount INTEGER NOT NULL);\nINSERT INTO ledger VALUES (1,1,''cash'',100),(2,1,''sales'',-100),(3,2,''cash'',-30),(4,2,''rent'',30),(5,3,''cash'',50),(6,3,''sales'',-40);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-conflict-graph', 9, 'func', 'Граф конфликтов расписания', 'Расписание — список операций [транзакция, ''r'' или ''w'', объект] в порядке выполнения. Две операции конфликтуют, если они над одним объектом, из разных транзакций и хотя бы одна — запись. Напишите conflict_edges(schedule): отсортированный список уникальных рёбер [Ti, Tj] — ребро ставится, когда конфликтующая операция Ti идёт раньше операции Tj.', 'def conflict_edges(schedule):
    pass
', 'Для каждой пары операций i < j: разные транзакции, один объект и хотя бы одна запись — ребро (Ti, Tj).', '{"func": "conflict_edges", "tests": [{"args": [[[1, "r", "x"], [2, "w", "x"], [1, "w", "y"]]], "expected": [[1, 2]]}, {"args": [[[1, "w", "x"], [2, "r", "x"], [2, "w", "y"], [3, "r", "y"]]], "expected": [[1, 2], [2, 3]]}, {"args": [[[1, "r", "x"], [2, "r", "x"]]], "expected": []}, {"args": [[[1, "w", "x"], [2, "w", "x"], [1, "w", "y"], [2, "w", "y"]]], "expected": [[1, 2]]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-serializable', 10, 'func', 'Сериализуемо ли расписание', 'Расписание — список [транзакция, ''r''/''w'', объект]. Расписание сериализуемо по конфликтам, если граф конфликтов (ребро Ti → Tj, когда конфликтующая операция Ti идёт раньше) не содержит циклов. Напишите is_serializable(schedule) → True/False.', 'def is_serializable(schedule):
    pass
', 'Постройте рёбра так же, как в предыдущей задаче, и поищите цикл поиском в глубину (состояния: не посещена, в стеке, закончена).', '{"func": "is_serializable", "tests": [{"args": [[[1, "r", "x"], [2, "w", "x"], [1, "w", "x"]]], "expected": false}, {"args": [[[1, "r", "x"], [1, "w", "x"], [2, "r", "x"], [2, "w", "x"]]], "expected": true}, {"args": [[[1, "w", "x"], [2, "w", "y"], [1, "w", "y"], [2, "w", "x"]]], "expected": false}, {"args": [[[1, "r", "x"], [2, "r", "x"], [3, "r", "x"]]], "expected": true}, {"args": [[]], "expected": true}, {"args": [[[1, "w", "x"], [2, "r", "x"], [3, "w", "x"], [2, "w", "y"], [3, "r", "y"]]], "expected": true}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-lock-compat', 11, 'func', 'Совместимость блокировок', 'Менеджер блокировок на один объект. held — список уже выданных блокировок [транзакция, режим], режим ''S'' (разделяемая) или ''X'' (исключительная). Напишите can_grant(held, tx, mode): можно ли выдать блокировку транзакции tx в режиме mode. Правила: S совместима с S; X несовместима ни с чем; блокировки самой tx не мешают ей же.', 'def can_grant(held, tx, mode):
    pass
', 'Проверяйте только чужие блокировки: если режим запроса X или чужая блокировка X — отказ.', '{"func": "can_grant", "tests": [{"args": [[], 1, "X"], "expected": true}, {"args": [[[1, "S"], [2, "S"]], 3, "S"], "expected": true}, {"args": [[[1, "S"]], 2, "X"], "expected": false}, {"args": [[[1, "X"]], 2, "S"], "expected": false}, {"args": [[[1, "S"]], 1, "X"], "expected": true}, {"args": [[[1, "S"], [2, "S"]], 1, "X"], "expected": false}, {"args": [[[1, "X"]], 1, "S"], "expected": true}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-deadlock', 12, 'func', 'Поиск взаимоблокировки', 'Граф ожиданий: словарь «транзакция → транзакция, которую она ждёт» (ключи — строки, например {"1": "2", "2": "1"}). Напишите find_deadlock(waits): отсортированный список транзакций, входящих в цикл ожидания, или [] если цикла нет (каждая транзакция ждёт не больше одной).', 'def find_deadlock(waits):
    pass
', 'Идите по цепочке ожиданий, запоминая посещённые; если вернулись в уже виденную транзакцию — это цикл.', '{"func": "find_deadlock", "tests": [{"args": [{"1": "2", "2": "1"}], "expected": ["1", "2"]}, {"args": [{"1": "2", "2": "3", "3": "1"}], "expected": ["1", "2", "3"]}, {"args": [{"1": "2", "2": "3"}], "expected": []}, {"args": [{}], "expected": []}, {"args": [{"1": "2", "2": "3", "3": "2", "4": "1"}], "expected": ["2", "3"]}, {"args": [{"5": "5"}], "expected": ["5"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-mvcc-visible', 13, 'func', 'Видимость версий строки (MVCC)', 'Версия строки — [xmin, xmax, значение], xmax = 0, если версия не удалена. Снимок: committed — список номеров зафиксировавшихся транзакций, me — номер текущей. Версия видна, если создана зафиксированной транзакцией или самой me, и не удалена зафиксированной транзакцией или самой me. Напишите visible(versions, committed, me): список значений видимых версий в исходном порядке.', 'def visible(versions, committed, me):
    pass
', 'Два независимых условия: создана видимой транзакцией и не удалена видимой транзакцией.', '{"func": "visible", "tests": [{"args": [[[10, 25, 100], [25, 0, 70]], [10, 25], 30], "expected": [70]}, {"args": [[[10, 25, 100], [25, 0, 70]], [10], 30], "expected": [100]}, {"args": [[[10, 0, 5]], [], 10], "expected": [5]}, {"args": [[[10, 25, 100], [25, 0, 70]], [10, 25], 25], "expected": [70]}, {"args": [[[1, 0, "a"], [2, 3, "b"], [3, 0, "c"]], [1, 2], 9], "expected": ["a", "b"]}, {"args": [[], [1], 1], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-dirty-reads', 14, 'func', 'Поиск грязных чтений', 'История одного объекта: события [тип, транзакция]: [''w'', t] — запись, [''r'', t] — чтение, [''c'', t] — фиксация, [''a'', t] — откат. Грязное чтение — когда транзакция читает объект, последнюю запись которого сделала другая, ещё не зафиксированная и не откатанная транзакция. Напишите dirty_reads(history): отсортированный список уникальных пар [читатель, писатель].', 'def dirty_reads(history):
    pass
', 'Храните автора последней записи и множество незавершённых транзакций; чтение чужой незавершённой записи — находка.', '{"func": "dirty_reads", "tests": [{"args": [[["w", 2], ["r", 1], ["a", 2]]], "expected": [[1, 2]]}, {"args": [[["w", 2], ["c", 2], ["r", 1]]], "expected": []}, {"args": [[["w", 1], ["r", 1]]], "expected": []}, {"args": [[["w", 1], ["r", 2], ["r", 3], ["c", 1]]], "expected": [[2, 1], [3, 1]]}, {"args": [[]], "expected": []}, {"args": [[["w", 1], ["w", 2], ["r", 3], ["c", 2], ["c", 1]]], "expected": [[3, 2]]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-lost-update', 15, 'func', 'Симуляция потерянного обновления', 'Два клиента делают «прочитать, прибавить, записать». Шаги — список [''r'', клиент] (прочитать текущее значение в локальную переменную) и [''w'', клиент, дельта] (записать локальное значение + дельта). Напишите final_balance(start, steps): значение после всех шагов. Клиент читает один раз перед записью.', 'def final_balance(start, steps):
    pass
', 'Каждый клиент хранит своё прочитанное значение; запись затирает общее значение, не учитывая чужие изменения.', '{"func": "final_balance", "tests": [{"args": [100, [["r", "a"], ["w", "a", 10], ["r", "b"], ["w", "b", 10]]], "expected": 120}, {"args": [100, [["r", "a"], ["r", "b"], ["w", "a", 10], ["w", "b", 10]]], "expected": 110}, {"args": [0, [["r", "a"], ["r", "b"], ["r", "c"], ["w", "c", 5], ["w", "b", 5], ["w", "a", 5]]], "expected": 5}, {"args": [50, []], "expected": 50}, {"args": [10, [["r", "x"], ["w", "x", -4]]], "expected": 6}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-apply-atomic', 16, 'func', 'Атомарное применение переводов', 'Остатки — словарь «счёт → сумма» (строковые ключи). Переводы — список [откуда, куда, сумма]. Примените все переводы по порядку как одну транзакцию: если какой-то перевод сделал бы остаток отрицательным, откатите всё и верните исходные остатки; иначе верните новые. Напишите apply_atomic(balances, transfers).', 'def apply_atomic(balances, transfers):
    pass
', 'Работайте с копией словаря; при первом отрицательном остатке верните исходный словарь.', '{"func": "apply_atomic", "tests": [{"args": [{"a": 100, "b": 0}, [["a", "b", 30], ["b", "a", 10]]], "expected": {"a": 80, "b": 20}}, {"args": [{"a": 100, "b": 0}, [["a", "b", 30], ["b", "a", 50]]], "expected": {"a": 100, "b": 0}}, {"args": [{"a": 10, "b": 10}, []], "expected": {"a": 10, "b": 10}}, {"args": [{"a": 5, "b": 5, "c": 0}, [["a", "b", 5], ["b", "c", 10], ["c", "a", 10]]], "expected": {"a": 10, "b": 0, "c": 0}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-version-check', 17, 'func', 'Оптимистичные обновления', 'Строки — словарь «id → [версия, значение]» (ключи строковые). Обновления — список [id, ожидаемая_версия, новое_значение]. Каждое обновление срабатывает, только если версия строки равна ожидаемой: тогда значение заменяется, а версия растёт на 1. Напишите optimistic_apply(rows, updates): пару [итоговые_строки, число_конфликтов].', 'def optimistic_apply(rows, updates):
    pass
', 'Сравнивайте версию с ожидаемой; несовпадение (или отсутствие строки) — конфликт, строка не меняется.', '{"func": "optimistic_apply", "tests": [{"args": [{"7": [1, "a"]}, [["7", 1, "b"], ["7", 1, "c"]]], "expected": [{"7": [2, "b"]}, 1]}, {"args": [{"7": [1, "a"]}, [["7", 1, "b"], ["7", 2, "c"]]], "expected": [{"7": [3, "c"]}, 0]}, {"args": [{"1": [3, "x"], "2": [1, "y"]}, [["1", 3, "z"], ["2", 2, "q"], ["9", 1, "n"]]], "expected": [{"1": [4, "z"], "2": [1, "y"]}, 2]}, {"args": [{}, []], "expected": [{}, 0]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-backoff', 18, 'func', 'Задержки между повторами', 'После ошибки сериализации транзакцию повторяют с экспоненциальной задержкой. Напишите backoff(tries, base, cap): список задержек для tries повторов — base, 2·base, 4·base, … но не больше cap.', 'def backoff(tries, base, cap):
    pass
', 'Задержка номер i равна base * 2**i, ограниченная сверху значением cap.', '{"func": "backoff", "tests": [{"args": [5, 10, 100], "expected": [10, 20, 40, 80, 100]}, {"args": [0, 10, 100], "expected": []}, {"args": [3, 1, 1000], "expected": [1, 2, 4]}, {"args": [6, 50, 400], "expected": [50, 100, 200, 400, 400, 400]}, {"args": [1, 500, 100], "expected": [100]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-isolation-levels', 19, 'func', 'Аномалии по уровням изоляции', 'Для уровня изоляции (строка) верните отсортированный список аномалий, которые он допускает по стандарту SQL, из набора: ''dirty'', ''non_repeatable'', ''phantom''. Уровни: ''READ UNCOMMITTED'', ''READ COMMITTED'', ''REPEATABLE READ'', ''SERIALIZABLE''. Напишите allowed_anomalies(level).', 'def allowed_anomalies(level):
    pass
', 'Чем выше уровень, тем меньше аномалий: заведите словарь «уровень → список».', '{"func": "allowed_anomalies", "tests": [{"args": ["READ UNCOMMITTED"], "expected": ["dirty", "non_repeatable", "phantom"]}, {"args": ["READ COMMITTED"], "expected": ["non_repeatable", "phantom"]}, {"args": ["REPEATABLE READ"], "expected": ["phantom"]}, {"args": ["SERIALIZABLE"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 18, 'd2-lock-order', 20, 'func', 'Единый порядок блокировок', 'Чтобы избежать дедлоков, все транзакции берут блокировки в одном порядке — по возрастанию номера строки. Напишите lock_order(requests): для каждого запроса (списка номеров строк, которые нужно заблокировать) верните отсортированный список без повторов; результат — список таких списков.', 'def lock_order(requests):
    pass
', 'sorted(set(r)) даёт строки по возрастанию без повторов.', '{"func": "lock_order", "tests": [{"args": [[[3, 1, 2], [2, 1]]], "expected": [[1, 2, 3], [1, 2]]}, {"args": [[[5, 5, 5]]], "expected": [[5]]}, {"args": [[]], "expected": []}, {"args": [[[10, 2], [7], []]], "expected": [[2, 10], [7], []]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-create-index', 0, 'sql', 'Первый индекс', 'Запрос SELECT * FROM orders WHERE customer_id = 7 просматривает таблицу целиком. Создайте индекс по customer_id (назовите его как угодно), чтобы план стал поиском по индексу.', '-- индекс для поиска заказов по customer_id
