INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-unique-index', 1, 'sql', 'Уникальный индекс', 'Адреса электронной почты в users должны быть уникальными, а поиск по ним — быстрым. Создайте один уникальный индекс по email.', '-- уникальный индекс по email
CREATE
', 'CREATE UNIQUE INDEX … ON users (email);', '{"check": "SELECT \"unique\", origin FROM pragma_index_list(''users'') WHERE name NOT LIKE ''sqlite_autoindex%''", "expected": [[1, "c"]], "expected_cols": ["unique", "origin"], "ordered": true, "setup": "CREATE TABLE users (id INTEGER PRIMARY KEY, email TEXT NOT NULL, name TEXT);\nINSERT INTO users VALUES (1,''a@x.ru'',''Анна''),(2,''b@x.ru'',''Борис''),(3,''c@x.ru'',''Вера'');\n"}');
