INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-left-prefix', 3, 'sql', 'Левый префикс', 'Есть индекс по (customer_id, status), а запрос SELECT * FROM orders WHERE status = ''paid'' по нему не искать. Создайте индекс, который сделает этот запрос поиском (индекс может начинаться с status).', '-- индекс для WHERE status = ''paid''
