INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-join-index', 10, 'sql', 'Индекс под соединение', 'Запрос соединяет order_items с products по product_id: SELECT p.title FROM order_items i JOIN products p ON p.id = i.product_id WHERE i.order_id = 4. Создайте индекс на order_items, чтобы строки позиций по заказу находились поиском (в плане — SEARCH i USING … order_id).', '-- индекс для WHERE i.order_id = ...
CREATE INDEX
', 'Индексируется столбец, по которому ищем позиции: order_id.', '{"check": "EXPLAIN QUERY PLAN SELECT p.title FROM order_items i JOIN products p ON p.id = i.product_id WHERE i.order_id = 4", "contains": ["SEARCH i USING"], "expected": [[3, 0, 55, "SEARCH i USING COVERING INDEX idx_items_order (order_id=?)"], [7, 0, 45, "SEARCH p USING INTEGER PRIMARY KEY (rowid=?)"]], "forbid": ["SCAN i"], "setup": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, city TEXT NOT NULL);\nCREATE TABLE products (id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, price INTEGER NOT NULL);\nCREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), created TEXT NOT NULL, status TEXT NOT NULL);\nCREATE TABLE order_items (order_id INTEGER NOT NULL REFERENCES orders(id), product_id INTEGER NOT NULL REFERENCES products(id), qty INTEGER NOT NULL, UNIQUE (order_id, product_id));\nINSERT INTO customers VALUES (1,''Анна'',''Москва''),(2,''Борис'',''Казань''),(3,''Вера'',''Москва''),(4,''Глеб'',''Тверь''),(5,''Дарья'',''Казань''),(6,''Егор'',''Москва'');\nINSERT INTO products VALUES (1,''Ноутбук'',''tech'',70000),(2,''Мышь'',''tech'',1500),(3,''Книга SQL'',''books'',900),(4,''Кофе'',''food'',600),(5,''Чай'',''food'',400),(6,''Наушники'',''tech'',5000);\nINSERT INTO orders VALUES (1,1,''2024-01-05'',''paid''),(2,1,''2024-02-10'',''paid''),(3,2,''2024-02-11'',''cancelled''),(4,3,''2024-03-01'',''paid''),(5,3,''2024-03-15'',''paid''),(6,3,''2024-04-02'',''new''),(7,5,''2024-04-03'',''paid''),(8,2,''2024-04-20'',''paid'');\nINSERT INTO order_items VALUES (1,1,1),(1,2,2),(2,3,1),(2,4,3),(3,5,2),(4,1,1),(4,6,1),(5,3,2),(5,4,1),(6,2,1),(7,5,5),(7,4,2),(8,6,2),(8,2,1);\n"}');
