SELECT
', 'Чем ближе доля к 1, тем лучше индекс; у status всего три значения — индекс по нему слабый.', '{"expected": [[0.167, 0.01]], "expected_cols": ["customer_sel", "status_sel"], "setup": "CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, city TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL, total INTEGER NOT NULL);\nINSERT INTO orders VALUES (1,1,''Казань'',''2024-02-02'',''new'',101);\nINSERT INTO orders VALUES (2,2,''Тверь'',''2024-03-03'',''cancelled'',102);\nINSERT INTO orders VALUES (3,3,''Омск'',''2024-04-04'',''paid'',103);\nINSERT INTO orders VALUES (4,4,''Москва'',''2024-05-05'',''new'',104);\nINSERT INTO orders VALUES (5,5,''Казань'',''2024-06-06'',''cancelled'',105);\nINSERT INTO orders VALUES (6,6,''Тверь'',''2024-07-07'',''paid'',106);\nINSERT INTO orders VALUES (7,7,''Омск'',''2024-08-08'',''new'',107);\nINSERT INTO orders VALUES (8,8,''Москва'',''2024-09-09'',''cancelled'',108);\nINSERT INTO orders VALUES (9,9,''Казань'',''2024-10-10'',''paid'',109);\nINSERT INTO orders VALUES (10,10,''Тверь'',''2024-11-11'',''new'',110);\nINSERT INTO orders VALUES (11,11,''Омск'',''2024-12-12'',''cancelled'',111);\nINSERT INTO orders VALUES (12,12,''Москва'',''2024-01-13'',''paid'',112);\nINSERT INTO orders VALUES (13,13,''Казань'',''2024-02-14'',''new'',113);\nINSERT INTO orders VALUES (14,14,''Тверь'',''2024-03-15'',''cancelled'',114);\nINSERT INTO orders VALUES (15,15,''Омск'',''2024-04-16'',''paid'',115);\nINSERT INTO orders VALUES (16,16,''Москва'',''2024-05-17'',''new'',116);\nINSERT INTO orders VALUES (17,17,''Казань'',''2024-06-18'',''cancelled'',117);\nINSERT INTO orders VALUES (18,18,''Тверь'',''2024-07-19'',''paid'',118);\nINSERT INTO orders VALUES (19,19,''Омск'',''2024-08-20'',''new'',119);\nINSERT INTO orders VALUES (20,20,''Москва'',''2024-09-21'',''cancelled'',120);\nINSERT INTO orders VALUES (21,21,''Казань'',''2024-10-22'',''paid'',121);\nINSERT INTO orders VALUES (22,22,''Тверь'',''2024-11-23'',''new'',122);\nINSE