INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-index-list', 12, 'sql', 'Какие индексы есть', 'Выведите названия индексов таблицы t по алфавиту через pragma_index_list (колонка name).', '-- индексы таблицы t
SELECT
', 'SELECT name FROM pragma_index_list(''t'') ORDER BY name; индекс t_a лишний, ведь есть t_ab.', '{"expected": [["t_a"], ["t_ab"], ["t_c"]], "expected_cols": ["name"], "ordered": true, "setup": "CREATE TABLE t (a INTEGER, b INTEGER, c INTEGER);\nCREATE INDEX t_a ON t (a);\nCREATE INDEX t_ab ON t (a, b);\nCREATE UNIQUE INDEX t_c ON t (c);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 19, 'd3-binary-search', 13, 'func', 'Бинарный поиск: число проб', 'Отсортированный список ключей — это страница индекса. Напишите probe_count(keys, target): пара [позиция или -1, число сравнений], где поиск ведётся делением пополам: mid = (lo + hi) // 2, одно сравнение на пробу.', 'def probe_count(keys, target):
    pass
