', 'Два SUM(CASE WHEN … THEN amount ELSE 0 END).', '{"expected": [[450, 250]], "expected_cols": ["n_total", "s_total"], "setup": "CREATE TABLE sales (id INTEGER PRIMARY KEY, day INTEGER NOT NULL, region TEXT NOT NULL, amount INTEGER NOT NULL, status TEXT NOT NULL);\nINSERT INTO sales VALUES (1,1,''N'',100,''ok''),(2,2,''N'',150,''ok''),(3,3,''N'',120,''cancelled''),(4,4,''N'',200,''ok''),(5,1,''S'',80,''ok''),(6,2,''S'',90,''cancelled''),(7,3,''S'',110,''ok''),(8,5,''S'',60,''ok'');\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-filter', 8, 'sql', 'FILTER', 'Для каждого региона выведите число продаж (n) и число отменённых (cancelled) с помощью COUNT(*) FILTER (WHERE …): колонки region, n, cancelled; по региону.', '-- COUNT(*) FILTER
