INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-recursive-subordinates', 9, 'sql', 'Все подчинённые', 'Выведите всех подчинённых Сергея (id 7) на всех уровнях: колонки id, name, level (1 — прямые); по level, затем по id.', '-- рекурсия вниз
WITH RECURSIVE
