INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-recursive-depth', 10, 'sql', 'Глубина дерева', 'Выведите максимальную глубину иерархии (директор — уровень 0): колонка depth.', '-- глубина
