INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-recursive-dates', 11, 'sql', 'Ряд дат', 'Сгенерируйте ряд из последовательных чисел от 1 до 7 рекурсивным выражением и выведите их сумму квадратов: колонка s (должно получиться 140).', '-- ряд чисел
