INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-not-exists', 12, 'sql', 'Отделы без руководителей-продавцов', 'Выведите сотрудников, у которых нет подчинённых: колонки id, name; по id. Используйте NOT EXISTS.', '-- NOT EXISTS
SELECT
', 'NOT EXISTS (SELECT 1 FROM emp s WHERE s.boss_id = e.id).', '{"expected": [[3, "Мария"], [4, "Пётр"], [6, "Олег"], [9, "Лев"], [10, "Ира"]], "expected_cols": ["id", "name"], "ordered": true, "setup": "CREATE TABLE emp (id INTEGER PRIMARY KEY, name TEXT NOT NULL, dept TEXT NOT NULL, boss_id INTEGER, salary INTEGER NOT NULL);\nINSERT INTO emp VALUES (1,''Ольга'',''IT'',NULL,500),(2,''Игорь'',''IT'',1,300),(3,''Мария'',''IT'',1,300),(4,''Пётр'',''IT'',2,200),(5,''Нина'',''HR'',1,250),(6,''Олег'',''HR'',5,150),(7,''Сергей'',''Sales'',1,280),(8,''Аня'',''Sales'',7,180),(9,''Лев'',''Sales'',7,180),(10,''Ира'',''Sales'',8,120);\n"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (9, 28, 'd12-except', 13, 'sql', 'Разность множеств', 'Выведите значения, которые есть в a, но нет в b (без повторов): колонка x; по возрастанию.', '-- EXCEPT
SELECT
